/* かなを候補の列にする。候補全体の直積を作らず、到達状態をたどる。 */
const ROMA={あ:['a'],い:['i','yi'],う:['u','wu','whu'],え:['e'],お:['o'],か:['ka','ca'],き:['ki'],く:['ku','cu','qu'],け:['ke'],こ:['ko','co'],さ:['sa'],し:['shi','si','ci'],す:['su'],せ:['se','ce'],そ:['so'],た:['ta'],ち:['chi','ti'],つ:['tsu','tu'],て:['te'],と:['to'],な:['na'],に:['ni'],ぬ:['nu'],ね:['ne'],の:['no'],は:['ha'],ひ:['hi'],ふ:['fu','hu'],へ:['he'],ほ:['ho'],ま:['ma'],み:['mi'],む:['mu'],め:['me'],も:['mo'],や:['ya'],ゆ:['yu'],よ:['yo'],ら:['ra'],り:['ri'],る:['ru'],れ:['re'],ろ:['ro'],わ:['wa'],を:['wo'],が:['ga'],ぎ:['gi'],ぐ:['gu'],げ:['ge'],ご:['go'],ざ:['za'],じ:['ji','zi'],ず:['zu'],ぜ:['ze'],ぞ:['zo'],だ:['da'],ぢ:['di','ji'],づ:['du','zu'],で:['de'],ど:['do'],ば:['ba'],び:['bi'],ぶ:['bu'],べ:['be'],ぼ:['bo'],ぱ:['pa'],ぴ:['pi'],ぷ:['pu'],ぺ:['pe'],ぽ:['po'],ー:['-'],ぁ:['xa','la'],ぃ:['xi','li'],ぅ:['xu','lu'],ぇ:['xe','le'],ぉ:['xo','lo'],ゃ:['xya','lya'],ゅ:['xyu','lyu'],ょ:['xyo','lyo']};
for(const [k,stems] of Object.entries({き:['ky'],し:['sh','sy'],ち:['ch','ty','cy'],に:['ny'],ひ:['hy'],み:['my'],り:['ry'],ぎ:['gy'],じ:['j','jy','zy'],び:['by'],ぴ:['py']}))for(const [small,v] of [['ゃ','a'],['ゅ','u'],['ょ','o']])ROMA[k+small]=stems.map(s=>s+v).concat(ROMA[k].flatMap(s=>ROMA[small].map(t=>s+t)));
function tokenize(kana){let a=[];for(let i=0;i<kana.length;i++){let k=kana[i],pair=kana.slice(i,i+2);if(k==='ん'){const n=kana[i+1];a.push(!n?['n','nn',"n'"]:!/[あいうえおやゆよ]/.test(n)?['n','nn',"n'"]:['nn',"n'"]);continue;}if(k==='っ'){const next=ROMA[kana.slice(i+1,i+3)]||ROMA[kana[i+1]]||[];a.push([...new Set(next.map(s=>s[0]).filter(s=>!/[aeioun]/.test(s))), 'xtu','ltu','xtsu','ltsu']);continue;}if(ROMA[pair]){a.push(ROMA[pair]);i++;}else if(ROMA[k])a.push(ROMA[k]);else throw Error('Unknown kana '+k);}return a;}
function pathFor(tokens,input){const memo=new Map();function visit(i,p){let key=i+':'+p;if(memo.has(key))return memo.get(key);if(i===tokens.length)return p===input.length?{complete:true,rest:''}:null;for(const s of tokens[i]){let rem=input.slice(p);if(rem.length<s.length&&s.startsWith(rem)){return {complete:false,rest:s.slice(rem.length)+tokens.slice(i+1).map(t=>t[0]).join('')};}if(input.startsWith(s,p)){let res=visit(i+1,p+s.length);if(res){memo.set(key,res);return res;}}}memo.set(key,null);return null;}return visit(0,0);}
function pathsFor(q,input){let first=null;for(const k of [q.kana,...q.aliases]){const r=pathFor(tokenize(k),input);if(r?.complete)return r;if(r&&!first)first=r;}return first;}
function normalizeRoman(s){return s.normalize('NFKC').toLowerCase().replace(/[\s・]/g,'');}
